import{c as r,Q as o,j as d,m as a}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-需求工程","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-需求工程"},"headers":[],"relativePath":"综合知识/软件工程/需求工程.md","filePath":"综合知识/软件工程/需求工程.md","lastUpdated":null}'),e={name:"综合知识/软件工程/需求工程.md"};function l(n,t,s,g,h,i){return o(),d("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 软件需求分类（业务需求/用户需求/系统需求/功能需求/非功能需求/设计约束）</li><li>[x] 需求获取方法（用户访谈/问卷调查/采样/JAD/情节串联板）</li><li>[x] 需求分析（结构化分析/DFD/数据字典/判定表/判定树/三大模型）</li><li>[x] 基于 UML 的需求分析（用例图/包图/类图）</li><li>[x] 需求定义（严格定义 vs 原型方法/SRS）</li><li>[x] 需求验证（需求评审/需求测试/需求基线）</li><li>[x] 需求管理（CCB/需求变更控制）</li><li>[x] KANO 模型（基本需求/期望需求/兴奋需求）</li><li>[x] 需求跟踪（正向/逆向/双向/需求跟踪矩阵）</li><li>[x] SRS 约束类型（设计约束/过程约束）</li><li>[x] 需求状态管理</li><li>[x] 需求优先级的区分（非所有需求同等重要）</li><li>[x] 架构质量属性（性能/可靠性/可用性/安全性/可修改性/功能性/可变性/互操作性）</li><li>[x] MDD 模型驱动（PIM/PSM/CIM）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件需求分类-★" tabindex="-1">一、软件需求分类 ★ <a class="header-anchor" href="#一、软件需求分类-★" aria-label="Permalink to &quot;一、软件需求分类 ★&quot;">​</a></h3><blockquote><p>软件需求是描述用户对软件系统期望的一系列条件或能力。层次：<strong>业务需求 &gt; 用户需求 &gt; 功能需求</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类别</th><th>说明</th><th>提出方</th></tr></thead><tbody><tr><td><strong>业务需求</strong></td><td>企业/客户对系统高层次目标要求，确定项目视图和范围</td><td>投资人、客户、市场部门</td></tr><tr><td><strong>用户需求</strong></td><td>用户的具体目标，描述用户使用系统的场景</td><td>用户访谈、问卷调查</td></tr><tr><td><strong>系统需求</strong></td><td>从系统角度详细说明，含功能需求、非功能需求、设计约束</td><td>需求分析人员</td></tr></tbody></table><p><strong>系统需求细分：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>功能需求</strong>（行为需求）</td><td>规定开发人员必须实现的软件功能</td></tr><tr><td><strong>非功能需求</strong></td><td>系统必须具备的属性或品质（可维护性、可靠性、效率等）</td></tr><tr><td><strong>设计约束</strong>（限制条件）</td><td>对系统的约束说明（特定技术、框架、数据库、操作系统等）</td></tr></tbody></table><hr><h3 id="二、需求获取-★" tabindex="-1">二、需求获取 ★ <a class="header-anchor" href="#二、需求获取-★" aria-label="Permalink to &quot;二、需求获取 ★&quot;">​</a></h3><blockquote><p>需求获取是确定和理解项目干系人需求和约束的过程。</p></blockquote><table tabindex="0"><thead><tr><th>方法</th><th>特点</th><th>关键记忆点</th></tr></thead><tbody><tr><td><strong>用户访谈</strong></td><td>1对1~3交流，结构化或非结构化</td><td>信息量大、记录困难、<strong>需要足够的领域知识</strong>，灵活性高</td></tr><tr><td><strong>问卷调查</strong></td><td>用户数量众多时使用</td><td>覆盖大量用户</td></tr><tr><td><strong>采样</strong></td><td>选取有代表性样本集</td><td>基于数理统计，减少数据收集偏差</td></tr><tr><td><strong>情节串联板</strong></td><td>图片/场景讲故事</td><td>直观表达需求</td></tr><tr><td><strong>联合需求计划（JAD）</strong></td><td>高度组织的群体会议</td><td>关键用户+分析师+开发团队一起讨论</td></tr></tbody></table><blockquote><p>口诀：<strong>访谈最灵活要懂行，采样统计少偏差，JAD 开会一起上。</strong></p></blockquote><hr><h3 id="三、需求分析-★" tabindex="-1">三、需求分析 ★ <a class="header-anchor" href="#三、需求分析-★" aria-label="Permalink to &quot;三、需求分析 ★&quot;">​</a></h3><blockquote><p>需求分析目的是将用户需求转化为<strong>清晰、准确、无歧义</strong>的需求，作为设计和实现的基础。</p></blockquote><p><strong>需求分析任务：</strong> 绘制系统上下文范围关系图 → 创建用户界面原型 → 分析需求可行性 → 确定需求优先级 → 为需求建立模型 → 创建数据字典 → QFD（质量功能部署）</p><h4 id="结构化分析方法" tabindex="-1">结构化分析方法 <a class="header-anchor" href="#结构化分析方法" aria-label="Permalink to &quot;结构化分析方法&quot;">​</a></h4><blockquote><p>结构化特点：<strong>自顶向下、逐步分解、面向数据</strong>。</p></blockquote><p><strong>三大模型：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><strong>功能模型</strong></td><td>数据流图（DFD）</td><td>表示系统输入、输出和处理过程</td></tr><tr><td><strong>行为模型</strong></td><td>状态转换图（STD）</td><td>表示系统状态和引起状态转换的事件</td></tr><tr><td><strong>数据模型</strong></td><td>E-R 图（实体-关系图）</td><td>表示数据元素及其关系</td></tr></tbody></table><p><strong>DFD 基本图形元素：</strong> 数据流、加工、数据存储、外部实体。</p><p><strong>DFD 常见错误：</strong></p><ul><li><strong>黑洞</strong>：有输入无输出的加工</li><li><strong>奇迹</strong>：有输出无输入的加工</li><li><strong>灰洞</strong>：输入不足以产生输出的加工</li></ul><p><strong>数据字典（DD）：</strong> 为 DFD 中元素提供详细定义，含数据流、数据项、数据存储、基本加工。</p><p><strong>需求分析方法：</strong> 结构化语言、判定表、判定树。</p><h4 id="基于-uml-的需求分析" tabindex="-1">基于 UML 的需求分析 <a class="header-anchor" href="#基于-uml-的需求分析" aria-label="Permalink to &quot;基于 UML 的需求分析&quot;">​</a></h4><ol><li>利用<strong>用例及用例图</strong>表示需求 → 获取执行者和场景 → 形成用例 → 生成用例图</li><li>利用<strong>包图和类图</strong>表示总体框架结构 → 提取&quot;关键概念&quot;形成领域概念模型 → 生成类图</li></ol><h4 id="_4-1-视图模型" tabindex="-1">4+1 视图模型 <a class="header-anchor" href="#_4-1-视图模型" aria-label="Permalink to &quot;4+1 视图模型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>视图</th><th>关注点</th><th>UML 对应</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>系统功能需求，最终用户</td><td>类图、对象图、状态图</td></tr><tr><td><strong>开发视图</strong>（实现视图）</td><td>软件模块组织管理，程序员</td><td>包图、组件图</td></tr><tr><td><strong>进程视图</strong></td><td>运行特性、并发/分布/容错，系统集成人员</td><td>活动图</td></tr><tr><td><strong>物理视图</strong>（部署视图）</td><td>软件→硬件映射、拓扑结构，系统工程师</td><td>部署图</td></tr><tr><td><strong>场景</strong>（用例视图）</td><td>使4个视图有机联系</td><td>用例图</td></tr></tbody></table><hr><h3 id="四、需求定义" tabindex="-1">四、需求定义 <a class="header-anchor" href="#四、需求定义" aria-label="Permalink to &quot;四、需求定义&quot;">​</a></h3><blockquote><p>产物：<strong>软件需求规格说明书（SRS）</strong>，是项目干系人共识文档，设计/实现/测试的依据。</p></blockquote><p><strong>两种定义方法：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>假设</th><th>特点</th></tr></thead><tbody><tr><td><strong>严格定义（预先定义）</strong></td><td>所有需求都能预先定义</td><td>图形或文字完整描述最终系统</td></tr><tr><td><strong>原型方法</strong></td><td>并非所有需求都能预先准确说明</td><td>迭代循环开发，逐步纳入需求，直到需求确定后遵循严格方法</td></tr></tbody></table><hr><h3 id="五、需求验证" tabindex="-1">五、需求验证 <a class="header-anchor" href="#五、需求验证" aria-label="Permalink to &quot;五、需求验证&quot;">​</a></h3><blockquote><p>目的：确保需求准确无误，与用户实际期望一致。</p></blockquote><p><strong>步骤：</strong></p><ol><li><strong>需求评审</strong>：正式评审（会议）或非正式评审（日常交流）</li><li><strong>需求测试</strong>：设计测试用例验证需求可实现的正确性</li></ol><p><strong>关键概念：</strong></p><ul><li>需求验证通过 → 用户签字确认 → SRS 成为<strong>需求基线</strong></li><li>需求基线是稳定参考点，之后任何更改需通过正式的<strong>需求变更流程</strong></li></ul><hr><h3 id="六、需求管理" tabindex="-1">六、需求管理 <a class="header-anchor" href="#六、需求管理" aria-label="Permalink to &quot;六、需求管理&quot;">​</a></h3><blockquote><p><strong>CCB（变更控制委员会）</strong>：对项目中任何基线工作产品的变更都可以做出决定。</p></blockquote><p><strong>需求变更管理流程</strong>：问题分析和变更描述 → 变更分析和成本计算 → 变更实现。</p><blockquote><p>需求的<strong>稳定性</strong>属于需求属性之一。CMM 可重复级有 <strong>6 个</strong>关键过程区域（非 3 个）。</p></blockquote><hr><h3 id="七、需求补充考点" tabindex="-1">七、需求补充考点 <a class="header-anchor" href="#七、需求补充考点" aria-label="Permalink to &quot;七、需求补充考点&quot;">​</a></h3><h4 id="kano-模型-★" tabindex="-1">KANO 模型 ★ <a class="header-anchor" href="#kano-模型-★" aria-label="Permalink to &quot;KANO 模型 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：需求按用户满意度维度分三级 — <strong>基本需求</strong>（不说也必须有）、<strong>期望需求</strong>（越多越好）、<strong>兴奋需求</strong>（锦上添花）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th>特征</th><th>示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>基本需求</strong></td><td>不满足→极度不满，满足→无感</td><td>手机APP控制灯光（智能家居标配）</td></tr><tr><td style="text-align:left;"><strong>期望需求</strong></td><td>满足度与实现度成正比</td><td>&quot;保存3秒内完成&quot;→ 期望更快</td></tr><tr><td style="text-align:left;"><strong>兴奋需求</strong></td><td>不满足→无感，满足→惊喜</td><td>超出预期的创新功能</td></tr></tbody></table><h4 id="需求跟踪-★" tabindex="-1">需求跟踪 ★ <a class="header-anchor" href="#需求跟踪-★" aria-label="Permalink to &quot;需求跟踪 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>正向跟踪</strong>=需求→下游工作产品；<strong>逆向跟踪</strong>=下游→回溯需求；需求跟踪矩阵可追溯从源头到实现的一致性。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">跟踪方式</th><th>方向</th><th>用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>正向跟踪</strong></td><td>SRS 需求→后续设计/代码/测试用例</td><td>检查每个需求是否都实现了</td></tr><tr><td style="text-align:left;"><strong>逆向跟踪</strong></td><td>后续工作产品→回溯到需求</td><td>检查每个实现是否有需求依据</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：「重构跟踪」不属于需求跟踪方式。</p></blockquote><p><strong>需求状态跟踪</strong>是需求管理活动之一。需求管理员活动包括：变更控制、版本控制、需求跟踪、需求状态跟踪（<strong>不包括文档管理</strong>）。</p><h4 id="srs-约束类型" tabindex="-1">SRS 约束类型 <a class="header-anchor" href="#srs-约束类型" aria-label="Permalink to &quot;SRS 约束类型&quot;">​</a></h4><blockquote><p>🎯 一句话结论：SRS 中约束分为 <strong>设计约束</strong>（技术/标准限制）和 <strong>过程约束</strong>（时间/资源/方法限制）。</p></blockquote><h4 id="需求管理补充" tabindex="-1">需求管理补充 <a class="header-anchor" href="#需求管理补充" aria-label="Permalink to &quot;需求管理补充&quot;">​</a></h4><ul><li>好的需求陈述：完整、准确描述功能；能够在约束内实现；是用户真正需要的</li><li>⚠️ <strong>不是所有需求都同等重要</strong>— 需求必须区分优先级</li><li>需求取（elicitation）是迭代过程：需求发现→分类组织→协商→文档化</li><li>需求专题讨论会的优势：有效解决不同涉众之间的需求冲突</li></ul><h4 id="架构质量属性-★" tabindex="-1">架构质量属性 ★ <a class="header-anchor" href="#架构质量属性-★" aria-label="Permalink to &quot;架构质量属性 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：考试常要求将需求归类到质量属性，8个核心质量属性务必记住。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">质量属性</th><th>说明</th><th>关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>性能</strong></td><td>响应时间、吞吐量、并发数</td><td>&quot;3秒内响应&quot;、&quot;支持100个设备&quot;</td></tr><tr><td style="text-align:left;"><strong>可靠性</strong></td><td>故障时维持功能的能力</td><td>&quot;故障自诊断和快速恢复&quot;</td></tr><tr><td style="text-align:left;"><strong>可用性</strong></td><td>正常运行的时间比例</td><td>&quot;7×24小时工作&quot;、&quot;0.5小时内恢复&quot;</td></tr><tr><td style="text-align:left;"><strong>安全性</strong></td><td>阻止非授权使用</td><td>&quot;密码加密传输&quot;、&quot;防XSS攻击&quot;、&quot;数据审计&quot;</td></tr><tr><td style="text-align:left;"><strong>可修改性</strong></td><td>快速以高性价比进行变更</td><td>&quot;支持个性化定制&quot;</td></tr><tr><td style="text-align:left;"><strong>功能性</strong></td><td>完成期望工作的能力</td><td>具体业务功能</td></tr><tr><td style="text-align:left;"><strong>可变性</strong></td><td>架构经扩充/变更成新架构</td><td>扩展性</td></tr><tr><td style="text-align:left;"><strong>互操作性</strong></td><td>与外部系统交互能力</td><td>&quot;支持主流标准和服务&quot;</td></tr></tbody></table><h4 id="mdd-模型驱动开发" tabindex="-1">MDD 模型驱动开发 <a class="header-anchor" href="#mdd-模型驱动开发" aria-label="Permalink to &quot;MDD 模型驱动开发&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">模型</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>CIM</strong></td><td>计算无关模型 — 业务视角</td></tr><tr><td style="text-align:left;"><strong>PIM</strong></td><td><strong>平台无关模型</strong> — 不涉及实现，对软件系统建模</td></tr><tr><td style="text-align:left;"><strong>PSM</strong></td><td>平台相关模型 — 绑定具体技术平台</td></tr></tbody></table>',66)])])}const q=r(e,[["render",l]]);export{u as __pageData,q as default};
